import { indexGraph, neighborhood } from './core/graph.js';
import { searchNodes } from './core/search.js';
import { findRoute } from './core/routing.js';
import { trainQ, traceQ, qRows } from './core/qlearning.js';
import { CanvasMap } from './ui/canvas-map.js';

const $=(s,r=document)=>r.querySelector(s); const $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>'"]/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[ch]));
const state={view:'map',lens:'all',selectedNode:null,selectedEdge:null,routeStart:null,routeGoal:null,routeMode:'shortest',route:null,Q:{},qEpisodes:0};
let graph,map;

async function init(){
  const raw=await fetch('./data/graph.json').then(r=>{if(!r.ok)throw new Error(`graph load ${r.status}`);return r.json()}); graph=indexGraph(raw);
  populateControls(); map=new CanvasMap($('#mapCanvas'),graph,{onNode, onEdge}); applyLens(); bind(); renderInspector(); renderStatus();
  const mand=[...graph.byId.values()].find(n=>n.title==='Mandelbrot set'); if(mand){state.selectedNode=mand.id;map.setSelection(mand.id);map.centerNode(mand.id);renderInspector()}
}
function bind(){
  $$('.view-tab').forEach(b=>b.addEventListener('click',()=>setView(b.dataset.view)));
  $('#lensSelect').addEventListener('change',e=>{state.lens=e.target.value;applyLens()});
  $('#fitBtn').addEventListener('click',()=>map.fit(true));
  $('#chaosToggle').addEventListener('change',e=>{map.setChaos(e.target.checked,+$('#tempRange').value,+$('#attractorRange').value,+$('#repulsionRange').value)}); $('#tempRange').addEventListener('input',e=>map.setChaos($('#chaosToggle').checked,+e.target.value,+$('#attractorRange').value,+$('#repulsionRange').value)); $('#attractorRange').addEventListener('input',()=>map.setChaos($('#chaosToggle').checked,+$('#tempRange').value,+$('#attractorRange').value,+$('#repulsionRange').value)); $('#repulsionRange').addEventListener('input',()=>map.setChaos($('#chaosToggle').checked,+$('#tempRange').value,+$('#attractorRange').value,+$('#repulsionRange').value));
  $('#searchBox').addEventListener('input',renderSearch); $('#searchBox').addEventListener('keydown',e=>{if(e.key==='Enter'){const r=searchNodes(graph,e.target.value,1)[0];if(r)selectNode(r.node.id)}});
  $('#routeStart').addEventListener('change',e=>{state.routeStart=e.target.value;computeRoute()}); $('#routeGoal').addEventListener('change',e=>{state.routeGoal=e.target.value;computeRoute()}); $('#routeMode').addEventListener('change',e=>{state.routeMode=e.target.value;computeRoute()}); $('#routeRun').addEventListener('click',computeRoute);
  $('#qTrain').addEventListener('click',trainQLab); $('#qReset').addEventListener('click',()=>{state.Q={};state.qEpisodes=0;renderQ();map.setRoute(null)}); $('#qTrace').addEventListener('click',()=>{const r=traceQ(graph,$('#qStart').value,$('#qGoal').value,state.Q);state.route=r;map.setRoute(r);renderRouteSummary(r);setView('map')}); $('#qExport').addEventListener('click',exportQ);
  $('#matrixSearch').addEventListener('input',renderMatrix); $('#matrixKind').addEventListener('change',renderMatrix); $('#indexSearch').addEventListener('input',renderIndex);
}
function populateControls(){
  $('#lensSelect').innerHTML=graph.lenses.map(l=>`<option value="${l.id}">${esc(l.title)}</option>`).join('');
  const opts=[...graph.nodes].sort((a,b)=>a.title.localeCompare(b.title)).map(n=>`<option value="${n.id}">${esc(n.title)}</option>`).join('');
  ['#routeStart','#routeGoal','#qStart','#qGoal'].forEach(s=>$(s).innerHTML=opts);
  state.routeStart=[...graph.byId.values()].find(n=>n.title==='Mandelbrot set')?.id||graph.nodes[0].id; state.routeGoal=[...graph.byId.values()].find(n=>n.title==='Mandelbulb')?.id||graph.nodes[1].id;
  $('#routeStart').value=state.routeStart;$('#routeGoal').value=state.routeGoal;$('#qStart').value=state.routeStart;$('#qGoal').value=state.routeGoal;
  const kinds=[...new Set(graph.edges.map(e=>e.kind))].sort();$('#matrixKind').innerHTML='<option value="">all provenance kinds</option>'+kinds.map(k=>`<option>${esc(k)}</option>`).join('');
}
function setView(v){state.view=v;$$('.view-tab').forEach(b=>b.classList.toggle('active',b.dataset.view===v));$$('.view').forEach(x=>x.classList.toggle('active',x.id===`view-${v}`));if(v==='index')renderIndex();if(v==='matrix')renderMatrix();if(v==='sources')renderSources();if(v==='routes')renderRoutes();if(v==='q')renderQ();if(v==='openrndr')renderOpenrndr();}
function lensNodeVisible(n,lens){if(lens.id==='all'||lens.id==='source'||lens.id==='q')return true;const cluster=lens.clusters.includes(n.primaryCluster),tag=(n.tags||[]).some(t=>lens.tags.some(x=>t.toLowerCase().includes(x.toLowerCase())));return cluster||tag}
function applyLens(){const lens=graph.lenses.find(l=>l.id===state.lens)||graph.lenses[0];let ids=new Set(graph.nodes.filter(n=>lensNodeVisible(n,lens)).map(n=>n.id));for(const e of graph.edges){if(ids.has(e.source)||ids.has(e.target)){if(e.kind==='source-backed annotation'||e.kind==='curated implementation bridge'){ids.add(e.source);ids.add(e.target)}}}map?.setVisible(ids);$('#lensNote').textContent=lens.description;renderStatus()}
function onNode(node,shift){if(shift){if(!state.routeStart||state.routeGoal){state.routeStart=node.id;state.routeGoal=null;$('#routeStart').value=node.id}else{state.routeGoal=node.id;$('#routeGoal').value=node.id;computeRoute()}return}selectNode(node.id)}
function selectNode(id){state.selectedNode=id;state.selectedEdge=null;map.setSelection(id);map.centerNode(id);renderInspector();renderStatus()}
function onEdge(edge){state.selectedEdge=edge.id;state.selectedNode=null;map.setSelection(null,edge.id);renderInspector();renderStatus()}
function renderSearch(){const box=$('#searchResults'),q=$('#searchBox').value.trim();if(!q){box.innerHTML='';box.hidden=true;return}const rows=searchNodes(graph,q);box.innerHTML=rows.map(({node})=>`<button data-id="${node.id}"><b>${esc(node.title)}</b><small>${esc(node.primaryCluster)} · ${esc(node.type)}</small></button>`).join('');box.hidden=!rows.length;$$('button',box).forEach(b=>b.onclick=()=>{selectNode(b.dataset.id);box.hidden=true;$('#searchBox').value='';setView('map')})}
function provenanceBadge(kind){const cls=kind.includes('curated')?'curated':kind.includes('source-backed')?'source':kind==='generated'?'generated':'captured';return `<span class="badge ${cls}">${esc(kind)}</span>`}
function renderInspector(){const p=$('#inspector');if(state.selectedNode){const n=graph.byId.get(state.selectedNode);const neigh=(graph.adjacency.get(n.id)||[]).sort((a,b)=>(b.edge.confidence??0)-(a.edge.confidence??0)).slice(0,12);p.innerHTML=`<div class="eyebrow">NODE · ${esc(n.type)}</div><h2>${esc(n.title)}</h2><p>${esc(n.description||clusterDescription(n.primaryCluster))}</p><div class="meta"><span>${esc(n.primaryCluster)}</span><span>degree ${n.degree}</span><span>${esc(n.provenance?.status)}</span></div><div class="actions"><button id="routeFrom">Route from</button><button id="routeTo">Route to</button><button id="expandNode">1-hop lens</button></div><h3>Connected to</h3><div class="connections">${neigh.map(x=>`<button data-node="${x.to}" data-edge="${x.edge.id}"><span>${esc(graph.byId.get(x.to)?.title)}</span>${provenanceBadge(x.edge.kind)}</button>`).join('')}</div>${renderSourcesForNode(n)}<details><summary>Canonical metadata</summary><pre>${esc(JSON.stringify({id:n.id,tags:n.tags,memberships:n.memberships,provenance:n.provenance},null,2))}</pre></details>`;
    $('#routeFrom').onclick=()=>{state.routeStart=n.id;$('#routeStart').value=n.id;computeRoute()};$('#routeTo').onclick=()=>{state.routeGoal=n.id;$('#routeGoal').value=n.id;computeRoute()};$('#expandNode').onclick=()=>{map.setVisible(neighborhood(graph,n.id,1));};$$('.connections button',p).forEach(b=>b.onclick=()=>selectNode(b.dataset.node));return}
  if(state.selectedEdge){const e=graph.edgeById.get(state.selectedEdge),a=graph.byId.get(e.source),b=graph.byId.get(e.target);p.innerHTML=`<div class="eyebrow">EDGE</div><h2>${esc(a.title)} <span class="arrow">${e.directional?'→':'↔'}</span> ${esc(b.title)}</h2><p class="relation">${esc(e.relation)}</p>${provenanceBadge(e.kind)}<dl><dt>confidence</dt><dd>${Number(e.confidence).toFixed(2)}</dd><dt>evidence count</dt><dd>${e.evidenceCount}</dd><dt>origin</dt><dd>${esc(e.origin)}</dd><dt>route base</dt><dd>${esc(e.kind)}</dd></dl><h3>Why this connection exists</h3><p>${esc(e.why)}</p>${e.kind.includes('curated')?'<div class="warning">Curated connection: useful for navigation/implementation context, not mathematical proof.</div>':''}${e.kind==='generated'?'<div class="warning">Generated structural metadata, not an independent factual claim.</div>':''}${(e.sources||[]).length?`<h3>Evidence/source</h3>${e.sources.map(s=>`<a href="./${esc(s)}" target="_blank">${esc(s)}</a>`).join('')}`:''}`;return}
  p.innerHTML='<div class="empty">Select a node or edge. Shift-click two nodes to route between them.</div>'
}
function clusterDescription(c){return graph.clusters[c]?.description||''}
function renderSourcesForNode(n){const caps=(n.capsules||[]).map(c=>`<a href="./${esc(c)}" target="_blank">local capsule · ${esc(c.split('/').pop())}</a>`).join('');const remote=n.source?`<a href="${esc(n.source)}" target="_blank" rel="noreferrer">remote source</a>`:'';const resources=(n.resources||[]).slice(0,8).map(r=>`<a href="${esc(r.url)}" target="_blank" rel="noreferrer">${esc(r.name)} <small>${esc(r.repo)}${r.path?' / '+esc(r.path):''}</small></a>`).join('');return (caps||remote||resources)?`<h3>Source material</h3><div class="source-links">${remote}${caps}${resources}</div>`:''}
function computeRoute(){state.routeStart=$('#routeStart').value;state.routeGoal=$('#routeGoal').value;state.routeMode=$('#routeMode').value;const r=state.routeMode==='q'?traceQ(graph,state.routeStart,state.routeGoal,state.Q):findRoute(graph,state.routeStart,state.routeGoal,state.routeMode);state.route=r;map.setRoute(r);renderRouteSummary(r);renderRouteComparison();renderStatus()}
function renderRouteSummary(r){const el=$('#routeSummary');if(!r){el.innerHTML='<span class="warning">No route found.</span>';return}el.innerHTML=`<div class="eyebrow">${esc(r.mode.toUpperCase())} ROUTE</div>${r.nodes.map((id,i)=>`<button data-id="${id}">${esc(graph.byId.get(id)?.title||id)}</button>${i<r.nodes.length-1?'<span>→</span>':''}`).join('')}<small>${r.reached===false?'Q trace did not reach goal · ':''}${r.cost!==undefined?'cost '+r.cost.toFixed(2)+' · ':''}${r.edges.length} edges</small>`;$$('button',el).forEach(b=>b.onclick=()=>selectNode(b.dataset.id))}
function renderRouteComparison(){const el=$('#routeCompare');if(!el||!state.routeStart||!state.routeGoal)return;const shortest=findRoute(graph,state.routeStart,state.routeGoal,'shortest'),math=findRoute(graph,state.routeStart,state.routeGoal,'mathematical');const card=(label,r,mode)=>!r?'':`<button class="compare-card" data-mode="${mode}"><span>${label}</span><b>${r.edges.length} edges</b><small>${r.nodes.map(id=>esc(graph.byId.get(id)?.title||id)).join(' → ')}</small></button>`;el.innerHTML=`<div class="eyebrow">SHORTEST ↔ MATHEMATICAL COMPARISON</div>${card('Shortest',shortest,'shortest')}${card('Mathematical',math,'mathematical')}`;$$('.compare-card',el).forEach(b=>b.onclick=()=>{$('#routeMode').value=b.dataset.mode;state.routeMode=b.dataset.mode;const r=findRoute(graph,state.routeStart,state.routeGoal,b.dataset.mode);state.route=r;map.setRoute(r);renderRouteSummary(r);renderStatus()})}
function renderIndex(){const q=$('#indexSearch').value||'';const rows=q?searchNodes(graph,q,200).map(x=>x.node):[...graph.nodes].sort((a,b)=>a.title.localeCompare(b.title));$('#indexTable tbody').innerHTML=rows.map(n=>`<tr data-id="${n.id}"><td>${esc(n.title)}</td><td>${esc(n.primaryCluster)}</td><td>${n.degree}</td><td>${(n.capsules||[]).length}</td><td>${(n.resources||[]).length}</td></tr>`).join('');$$('#indexTable tbody tr').forEach(r=>r.onclick=()=>{selectNode(r.dataset.id);setView('map')})}
function renderMatrix(){const q=($('#matrixSearch').value||'').toLowerCase(),kind=$('#matrixKind').value;const rows=graph.edges.filter(e=>(!kind||e.kind===kind)&&(!q||`${graph.byId.get(e.source)?.title} ${e.relation} ${graph.byId.get(e.target)?.title} ${e.kind}`.toLowerCase().includes(q)));$('#matrixTable tbody').innerHTML=rows.map(e=>`<tr data-id="${e.id}"><td>${esc(graph.byId.get(e.source)?.title)}</td><td>${esc(e.relation)}</td><td>${esc(graph.byId.get(e.target)?.title)}</td><td>${provenanceBadge(e.kind)}</td><td>${e.directional?'→':'↔'}</td><td>${Number(e.confidence).toFixed(2)}</td><td>${e.evidenceCount}</td></tr>`).join('');$$('#matrixTable tbody tr').forEach(r=>r.onclick=()=>{onEdge(graph.edgeById.get(r.dataset.id));setView('map')})}
function renderSources(){const rows=graph.nodes.filter(n=>n.source||(n.capsules||[]).length||(n.resources||[]).length).sort((a,b)=>a.title.localeCompare(b.title));$('#sourceList').innerHTML=rows.map(n=>`<article><h3>${esc(n.title)}</h3><p>${esc(n.primaryCluster)}</p>${renderSourcesForNode(n)}</article>`).join('')}
function renderRoutes(){computeRoute();}
function trainQLab(){const episodes=Math.max(10,Math.min(20000,+$('#qEpisodes').value||1200));state.Q=trainQ(graph,{start:$('#qStart').value,goal:$('#qGoal').value,episodes,alpha:+$('#qAlpha').value,gamma:+$('#qGamma').value,epsilon:+$('#qEpsilon').value,previous:state.Q});state.qEpisodes+=episodes;renderQ()}
function renderQ(){const rows=qRows(graph,$('#qGoal').value,state.Q).slice(0,220);$('#qMetrics').innerHTML=`<span>states <b>${graph.nodes.length}</b></span><span>actions <b>${graph.edges.length*2}</b></span><span>episodes <b>${state.qEpisodes}</b></span><span>max Q <b>${Math.max(0,...Object.values(state.Q)).toFixed(2)}</b></span>`;$('#qTable tbody').innerHTML=rows.map(r=>`<tr><td>${esc(graph.byId.get(r.state)?.title)}</td><td>→ ${esc(graph.byId.get(r.to)?.title)}</td><td>${esc(r.edge.kind)}</td><td>${r.reward.toFixed(2)}</td><td>${r.q.toFixed(3)}</td></tr>`).join('')}
function exportQ(){const blob=new Blob([JSON.stringify({schema:'fractal-chaos-q.v1',warning:'Q-values are learned navigation utility, not mathematical truth or proof.',start:$('#qStart').value,goal:$('#qGoal').value,episodes:state.qEpisodes,Q:state.Q},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='q-table.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500)}
function renderOpenrndr(){const nodes=graph.nodes.filter(n=>n.primaryCluster==='openrndr').sort((a,b)=>(a.id==='or-root'?-1:b.id==='or-root'?1:a.title.localeCompare(b.title)));$('#openrndrCards').innerHTML=nodes.map(n=>`<article data-id="${n.id}"><div class="eyebrow">${esc(n.type)}</div><h3>${esc(n.title)}</h3><p>${esc(n.description||'')}</p><div class="tags">${(n.tags||[]).slice(0,8).map(t=>`<span>${esc(t)}</span>`).join('')}</div>${renderSourcesForNode(n)}</article>`).join('');$$('#openrndrCards article').forEach(a=>a.onclick=e=>{if(e.target.tagName==='A')return;selectNode(a.dataset.id);setView('map')})}
function renderStatus(){const sel=state.selectedNode?graph.byId.get(state.selectedNode)?.title:state.selectedEdge?state.selectedEdge:'none';$('#status').textContent=`${graph.nodes.length} nodes · ${graph.edges.length} edges · lens ${state.lens} · selected ${sel}`}

init().catch(err=>{$('#bootError').hidden=false;$('#bootError').textContent=`Failed to start: ${err.stack||err}`;console.error(err)});
